To state the Schur complement sparsity $E^{(2)}$ explicitly, note
that the problem data $(\A,\b,\c,\K)$ in Step 2 of \algref{myalg}
are \begin{subequations}\label{eq:AKdef}
\begin{equation}
\begin{array}{c}
\A=[\svec_{F}(A_{1}),\dots,\svec_{F}(A_{m}),-\P_{1},\dots,-\P_{n}],\\
\b=-\svec_{F}(C),\qquad\c=(b,0),\\
\K=\R_{+}^{m}\times\svec(\S_{+}^{\omega_{1}})\times\svec(\S_{+}^{\omega_{2}})\times\cdots\times\svec(\S_{+}^{\omega_{n}})
\end{array}\label{eq:AKdef-1}
\end{equation}
where $\omega_{j}\equiv|\col_{F}(j)|$ and each $\P_{j}$ is implicitly
defined to satisfy 
\begin{equation}
\P_{j}^{T}\svec_{F}(Y)=\svec(Y[\col_{F}(j),\col_{F}(j)])\quad\text{for all }Y\in\S_{F}^{n}.\label{eq:AKdef-2}
\end{equation}
\end{subequations}The resulting Schur complement matrix reads
\begin{gather}
\A\nabla^{2}f(w)\A^{T}=\sum_{i=1}^{m}d_{i}\svec_{F}(A_{i})\svec_{F}(A_{i})^{T}+\sum_{j=1}^{n}\P_{j}\D_{j}\P_{j}^{T}\label{eq:Hessdef}\\
\text{where }d_{i}=w_{i}^{-2},\qquad\D_{j}\svec(X_{j})=\svec(W_{j}^{-1}X_{j}W_{j}^{-1})\nonumber 
\end{gather}
and $w=(w_{1},\dots,w_{m},\svec(W_{1}),\dots,\svec(W_{n}))\in\interior(\K)$
is a scaling point. The associated sparsity pattern, aggregated over
all possible choices of scaling $w$, is as follows
\begin{align}
E^{(2)} & =\{(i,j):(\A\nabla^{2}f(w)\A^{T})[i,j]\ne0\text{ for some }w\in\interior(\K)\}\nonumber \\
 & =\left(\bigcup_{i=1}^{m}\spar(a_{i}a_{i}^{T})\right)\cup\left(\bigcup_{j=1}^{n}\spar(\P_{j}\D_{j}\P_{j}^{T})\right)\nonumber \\
 & =\left(\bigcup_{i=1}^{m}\clique(\supp(a_{i}))\right)\cup\left(\bigcup_{j=1}^{n}\clique(\supp(\P_{j}))\right)\label{eq:E2def}
\end{align}
where we have written $a_{i}=\svec_{F}(A_{i})$. The result below
says that if $\omega(\o E)=O(1)$, then $\omega(\o E^{(2)})=O(1)$.

Our proof is based on the fact that the ``lifted'' sparsity pattern
$F^{(2)}$ can be constructed as $F^{(2)}=\bigcup_{k=1}^{n}\clique(J_{k}^{(2)})$
with respect to the following ``lifted'' index sets
\begin{gather}
J_{k}^{(2)}\equiv\idx_{F}(\clique(J_{k}))=\{\idx_{F}(i,j):i,j\in J_{k},\quad i\ge j\}.\label{eq:Jk2_def}
\end{gather}
We need to show that, if the original index sets $J_{1},J_{2},\dots,J_{k}$
satisfy the running intersection property, then the lifted index sets
$J_{1}^{(2)},J_{2}^{(2)},\dots,J_{k}^{(2)}$ will inherit the running
intersection property. Our key insight is that the index operator
$\idx_{F}$ implements a \emph{raster ordering}.
\begin{lemma}[Raster ordering]
The ordering $\idx_{F}:F\to\N$ satisfies the following, for all
$(i,j)\in F$ with $i\ge j$ and $(i',j')\in F$ with $i'\ge j'$:
\begin{itemize}
\item If $j>j'$, then $\idx(i,j)>\idx(i',j')$ holds. 
\item If $j=j'$ and $i>i'$, then $\idx(i,j)>\idx(i',j')$ holds. 
\end{itemize}
\end{lemma}

\begin{proposition}[Sparse Cholesky factorization]
\label{prop:chol}Given $S\in\S^{n},$ $S\succ0$, let $\omega\equiv\omega(S)$.
Sparse Cholesky factorization factors $L=\chol(S)$ in $\Tim$ arithmetic
operations and $M$ units of memory, where 
\begin{align*}
\frac{1}{6}(\omega-1)^{3}+n & \le\Tim\le\omega^{2}\cdot n, & \frac{1}{2}(\omega-1)^{2}+n & \le\Mem\le\omega\cdot n.
\end{align*}
\end{proposition}

\begin{proof}
It is known that $(i,j)\in\chol(E)$ for $i>j$ holds if and only
if there exists a path $(i,p_{1},p_{2},\dots,p_{\ell},j)$ whose edges
are in $E$, and whose internal nodes are ordered $p_{1},p_{2},\dots,p_{\ell}<j<i$;
see e.g.~\citep[Theorem~6.1]{vandenberghe2015chordal}. It immediately
follows this characterization that $\chol(\cdot)$ is monotone with
respect to the deletion of edges and isolated vertices: (1) if $D\subseteq E$,
then $\chol(D)\subseteq\chol(E)$; (2) we have $\chol(E[U])=\chol(E)[U]$
for $U=\{1,2,\dots,n\}\backslash v$ with isolated vertex $v$. Therefore,
$\chol(\cdot)$ must also be monotone under general vertex and edge
deletions, because we can always delete edges to isolate a vertex
before deleting it. \qed
\end{proof}

\begin{lemma}
\label{lem:lift}Let the sequence of subsets $J_{1},J_{2},\dots,J_{\ell}$
with $J_{j}\subset\N$ satisfy the sorted running intersection property.
Then, $J_{1}^{(2)},J_{2}^{(2)},\dots,J_{\ell}^{(2)}$ also satisfy
the sorted running intersection property. 
\end{lemma}

\begin{lemma}
\label{lem:colrip}Let $J_{1},J_{2},\dots,J_{\ell}$ with $\bigcup_{j=1}^{\ell}J_{j}=\{1,2,\dots,n\}$
satisfy the sorted running intersection property. For every $j$-th
column in $F=\bigcup_{j=1}^{\ell}\clique(J_{j})$, there exists some
$J_{w}$ such that $\col_{F}(j)\subseteq J_{w}.$
\end{lemma}

\begin{lemma}
For every $i\in\{1,2,\dots,m\}$, there exists $k\in\{1,2,\dots,n\}$
such that $\supp(a_{i})\subseteq\supp(\o{\P}_{k})[V^{(2)}]$ where
$V^{(2)}=\{\idx_{\overline{F}}(i,j):i,j\in F\}$. 
\end{lemma}

\begin{proof}
It follows by repeating the proof of \lemref{quadlift} that
\begin{gather*}
\supp(\o{\P}_{k})=\{\idx_{\o F}(i,j):i,j\in\col_{\o F}(k),i\ge j\},\\
\supp(\o{\P}_{k})[V^{(2)}]=\{\idx_{F}(i,j):i,j\in\col_{\o F}(k),i\ge j\}.
\end{gather*}
Our desired claim follows via the following sequence of inclusions
\begin{align*}
\supp(a_{i}) & =\{v:a_{i}[v]\ne0\}=\{\idx_{F}(u,v):A_{i}[u,v]\ne0,\quad(u,v)\in F\}\\
 & \overset{\text{(a)}}{\subseteq}\{\idx_{F}(u,v):u,v\in\supp(A_{i}),\quad(u,v)\in F\}\\
 & \overset{\text{(b)}}{\subseteq}\{\idx_{F}(u,v):u,v\in\col_{\o F}(k),\quad(u,v)\in F\}=\supp(\o{\P}_{k})[V^{(2)}].
\end{align*}
Inclusion (a) is because $\spar(A_{i})\subseteq\clique(\supp(A_{i}))$.
Inclusion (b) is true via the following: If $J=\supp(A_{i})$ satisfies
$\clique(J)\subseteq\o F$, then $J\subseteq\col_{\o F}(k)$ where
$k=\min J$. Indeed, we have $k\in\col_{\o F}(k)$ by definition.
For any arbitrary $j\in J$ with $j>k$, we must have an edge $(j,k)\in\clique(J)\subseteq\o F$,
and therefore $j\in\col_{\o F}(k)$. \qed
\end{proof}

\begin{lemma}
For every $k\in\{1,2,\dots,n\}$, we have $\supp(\P_{k})\subseteq\supp(\o{\P}_{k})[V^{(2)}]$
where $V^{(2)}=\{\idx_{\overline{F}}(i,j):i,j\in F\}$. 
\end{lemma}

\begin{proof}
It again follows by repeating the proof of \lemref{quadlift} that
\begin{align*}
\supp(\P_{k}) & =\{\idx_{F}(i,j):i,j\in\col_{F}(k),i\ge j\}\\
 & \overset{\text{(a)}}{\subseteq}\{\idx_{F}(i,j):i,j\in\col_{\o F}(k),i\ge j\}=\supp(\o{\P}_{k})[V^{(2)}].
\end{align*}
Inclusion (a) is true because $E\subseteq\o E$ implies $F=\chol(E)\subseteq\chol(\o E)=\o F$
via \propref{del}, and therefore $\col_{F}(k)\subseteq\col_{\o F}(k)$.
\qed
\end{proof}

\begin{lemma}[Linear independence]
We have $\A^{T}y=0$ if and only $y=0$. 
\end{lemma}

