\end{equation}
where $\D=[\nabla^{2}f(w)]^{-1}$ and $d=-s-\mu^{+}\nabla f(x)$,
and 
\begin{equation}
\begin{bmatrix}u_{1} & u_{2} & u_{3}\end{bmatrix}=\D(\begin{bmatrix}d & c & r_{d}\end{bmatrix}+\A^{T}\begin{bmatrix}v_{1} & v_{2} & v_{3}\end{bmatrix}),\label{eq:hsd_back1}
\end{equation}
then
\begin{align}
\left(\begin{bmatrix}-\D_{0}^{-1} & -r_{c}\\
r_{c} & 0
\end{bmatrix}-\begin{bmatrix}\c & r_{d}\\
-\b & r_{p}
\end{bmatrix}^{T}\begin{bmatrix}u_{2} & u_{3}\\
v_{2} & v_{3}
\end{bmatrix}\right)\begin{bmatrix}\Delta\tau\\
\Delta\theta
\end{bmatrix} & =\begin{bmatrix}-d_{0}\\
0
\end{bmatrix}-\begin{bmatrix}\c & r_{d}\\
-\b & r_{p}
\end{bmatrix}^{T}\begin{bmatrix}u_{1}\\
v_{1}
\end{bmatrix},\\
\begin{bmatrix}\Delta x\\
\Delta y
\end{bmatrix} & =\begin{bmatrix}u_{1}\\
v_{1}
\end{bmatrix}-\begin{bmatrix}u_{1} & u_{2}\\
v_{1} & v_{2}
\end{bmatrix}\begin{bmatrix}\Delta\tau\\
\Delta\theta
\end{bmatrix},\\
\Delta s & =d-\D^{-1}\Delta x,\\
\Delta\kappa & =d_{0}-\D_{0}^{-1}\Delta\tau,\label{eq:hsd_back2}
\end{align}
\end{subequations}where $\D_{0}=\tau/\kappa$ and $d_{0}=-\kappa+\mu^{+}\tau^{-1}$.
Therefore, we conclude that the cost of computing the search direction
in (\ref{eq:hsd_nt}) is equal to the cost of solving $O(1)$ instances
of the Schur complement equation $\A\D\A^{T}\Delta y=g$, plus $O(1)$
matrix-vector products with $\A,\A^{T},\D,\D^{-1}$, for a total cost
of $O(\Tim+\nnz(\A)+\omega^{2}n)$ time and $O(\Mem+\nnz(\A)+\omega n)$
memory respectively. Note that $\A\D\A^{T}\succ0$ because $\A\A^{T}\succ0$
by the linear independence assumption, and $\D^{-1}=\nabla^{2}f(w)\succ0$
for all $w\in\interior(\K)$.
\end{enumerate}
\qed \end{proof}

